&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Cha&quot;&gt;Cha&lt;/a&gt; 13, &lt;a class=&quot;pagelink&quot; href=&quot;Orque-(Race).html&quot; title=&quot;Les orques&quot;&gt;orque&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Demi-Orque.html&quot; title=&quot;Les demi-orques&quot;&gt;demi-orque&lt;/a&gt;, non-Loyal&lt;/td&gt;&lt;td&gt;Les alli&#233;s du personnage continuent de profiter des rages mineures obtenues par la proximit&#233; avec le personnage &#224; 9 m de distance&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rage-Empathique.html&quot; title=&quot;Rage empathique&quot;&gt;Rage empathique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Orque-(Race).html&quot; title=&quot;Les orques&quot;&gt;Orque&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Demi-Orque.html&quot; title=&quot;Les demi-orques&quot;&gt;demi-orque&lt;/a&gt;, non-Loyal&lt;/td&gt;&lt;td&gt;Le personnage peut entrer dans une rage mineure lorsqu’il est pr&#232;s d’alli&#233;s enrag&#233;s&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;T&#233;nacit&#233;-F&#233;roce.html&quot; title=&quot;T&#233;nacit&#233; f&#233;roce&quot;&gt;T&#233;nacit&#233; f&#233;roce&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Orque-(Race).html&quot; title=&quot;Les orques&quot;&gt;Orque&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Demi-Orque.html&quot; title=&quot;Les demi-orques&quot;&gt;demi-orque&lt;/a&gt;, trait racial de &lt;a class=&quot;pagelink&quot; href=&quot;Orque-(Race).html#Traits_raciaux_standards_6&quot; title=&quot;Les orques&quot;&gt;f&#233;rocit&#233;&lt;/a&gt;, aptitude de classe de &lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html#RAGE&quot; title=&quot;Le barbare&quot;&gt;rage de berserker&lt;/a&gt;&lt;/td&gt;&lt;td&gt;D&#233;pense des rounds de rage pour r&#233;duire des d&#233;g&#226;ts mortels&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vengeance-Sanguinaire.html&quot; title=&quot;Vengeance sanguinaire&quot;&gt;Vengeance sanguinaire&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Orque-(Race).html&quot; title=&quot;Les orques&quot;&gt;Orque&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Demi-Orque.html&quot; title=&quot;Les demi-orques&quot;&gt;demi-orque&lt;/a&gt;, non-Loyal&lt;/td&gt;&lt;td&gt;Le personnage peut entrer dans une rage mineure lorsqu’un alli&#233; est tu&#233; ou gravement bless&#233;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;49%&quot;&gt;
&lt;h3 class=&quot;separator&quot;&gt;Arch&#233;types de classe&lt;a class=&quot;headeranchor&quot; id=&quot;Arch&#233;types_de_classe_1&quot; href=&quot;#Arch&#233;types_de_classe_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Combattant-D&#233;loyal-(Guerrier).html&quot; title=&quot;Combattant d&#233;loyal&quot;&gt;Combattant d&#233;loyal (guerrier)&lt;/a&gt; &lt;i&gt;(MR)&lt;/i&gt;&lt;/li&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gu&#233;risseuse-Balafr&#233;e-(Sorci&#232;re).html&quot; title=&quot;Gu&#233;risseuse balafr&#233;e&quot;&gt;Gu&#233;risseuse balafr&#233;e (sorci&#232;re)&lt;/a&gt; &lt;i&gt;(MR)&lt;/i&gt;&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;&#201;quipement&lt;a class=&quot;headeranchor&quot; id=&quot;&#201;quipement_2&quot; href=&quot;#&#201;quipement_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Besace-Desprit-Guerrier-(Objet).html&quot; title=&quot;Besace d&amp;#39;esprit guerrier&quot;&gt;Besace d’esprit guerrier&lt;/a&gt; &lt;i&gt;(MR)&lt;/i&gt;&lt;/li&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;tendard-Tribal-(Objet).html&quot; title=&quot;&#201;tendard tribal&quot;&gt;&#201;tendard tribal&lt;/a&gt; &lt;i&gt;(MR)&lt;/i&gt;&lt;/li&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Harnais-&#192;-Corne-(Objet).html&quot; title=&quot;Harnais &#224; corne&quot;&gt;Harnais &#224; corne&lt;/a&gt; &lt;i&gt;(CM)&lt;/i&gt;&lt;/li&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Masque-De-Guerre-(Objet).html&quot; title=&quot;Masque de guerre&quot;&gt;Masque de guerre&lt;/a&gt; &lt;i&gt;(MR)&lt;/i&gt;&lt;/li&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Selle-De-Gorthek-(Objet).html&q